const { configuredRoutes } = require('./control-bound-protocol')
const { meterRoute } = require('./meter-route')
const { xySeriesRoute } = require('./xy-series-route')
const { targetStates, isMeterTarget } = require('./control-type-model')
const { availabilityRoute } = require('./device-availability')

const supportedTypes = {
  boolean: { eventType: 'Boolean', eventOptions: { boolParamFilter: 'Any' } },
  integer: { eventType: 'Integer', eventOptions: { normalized: false } },
  float: { eventType: 'Float', eventOptions: { normalized: false } },
  string: { eventType: 'String', eventOptions: {} },
  dstring: { eventType: 'DString (comma separated string)', eventOptions: {} },
  enum: { eventType: 'Enumeration', eventOptions: {} }
}

function compileNativeBindingPlan ({ panel, targets, scopeId }) {
  if (!/^[A-Za-z][A-Za-z0-9_-]{0,48}$/.test(scopeId || '')) {
    throw new Error('A unique, stable scopeId is required')
  }
  if (!Array.isArray(targets)) throw new Error('Target descriptors are required')
  const routes = configuredRoutes(panel)
  if (!routes.size) throw new Error('No visual bindings to compile')

  const targetIndex = new Map()
  for (const target of targets) {
    const key = JSON.stringify([target.device, target.path])
    if (targetIndex.has(key)) throw new Error(`Duplicate target descriptor: ${key}`)
    targetIndex.set(key, target)
  }

  const subflowId = `${scopeId}-bridge`
  const nodes = []
  const readTargets = new Map()
  const writeTargets = new Map()
  const meterStreams = new Map()
  const xySeriesStreams = new Map()
  const healthTargets = new Map()
  const commandRules = []
  const commandWires = []

  function metadata (device, path, type, access, adapter) {
    const target = targetIndex.get(JSON.stringify([device, path]))
    if (!target) throw new Error(`Missing target descriptor: ${device} ${path}`)
    if (target.kind !== 'param') throw new Error(`Only parameter targets are supported: ${path}`)
    if (!target.xySeries && !Object.hasOwn(supportedTypes, target.type)) {
      throw new Error(`Unsupported native parameter type: ${path} (${target.type})`)
    }
    if (['mute', 'power'].includes(type) && !targetStates(target) &&
      !(target.type === 'integer' && target.booleanEncoding === 'integer01')) {
      throw new Error(`Boolean control bound to ${target.type}: ${path}`)
    }
    if (['level', 'dimmer', 'position'].includes(type) &&
      (!['integer', 'float'].includes(target.type) || (adapter === 'range' && isMeterTarget(target)))) {
      throw new Error(`Numeric control bound to ${target.type}: ${path}`)
    }
    if (type === 'text' && !['string', 'dstring'].includes(target.type)) {
      throw new Error(`Text control bound to ${target.type}: ${path}`)
    }
    if (['source', 'preset'].includes(type) && !['enum', 'integer', 'string'].includes(target.type)) {
      throw new Error(`Choice control bound to ${target.type}: ${path}`)
    }
    if (type === 'meter' && !isMeterTarget(target)) {
      throw new Error(`Meter control must bind to a readonly Meter target: ${path}`)
    }
    if (type === 'xy-series' && (!target.xySeries || target.access !== 'ro')) {
      throw new Error(`XY-series control must bind to a readonly XY-series target: ${path}`)
    }
    if (!['mute', 'power', 'level', 'dimmer', 'position', 'meter', 'xy-series', 'text', 'source', 'preset'].includes(type)) {
      throw new Error(`Control type requires a separate command adapter: ${type}`)
    }
    if (!['ro', 'wo', 'rw'].includes(target.access) || !target.access.includes(access)) {
      throw new Error(`Target is not ${access === 'r' ? 'readable' : 'writable'}: ${path}`)
    }
    if (typeof target.onebased !== 'boolean') {
      throw new Error(`Target numbering mode is required: ${path}`)
    }
    if (target.availability) {
      for (const point of Object.values(availabilityRoute(target.availability, target.onebased))) {
        const key = JSON.stringify([device, point.path])
        if (healthTargets.has(key)) {
          if (healthTargets.get(key).onebased !== point.onebased) throw Error('Conflicting availability numbering')
          continue
        }
        const index = healthTargets.size + 1
        const statusId = `${scopeId}-health-read-${index}`
        const eventId = `${scopeId}-health-watch-${index}`
        const tagId = `${scopeId}-health-tag-${index}`
        healthTargets.set(key, { statusId, tagId, onebased: point.onebased })
        nodes.push({ id: statusId, type: 'Status', z: subflowId,
          name: `Read availability ${device} ${point.path}`, x: 440, y: 340 + index * 170,
          mojo: { version: '1.0', device: [device], parameter: point.path, onebased: point.onebased }, wires: [[tagId]] })
        nodes.push({ id: eventId, type: 'Event', z: subflowId,
          name: `Watch availability ${device} ${point.path}`, x: 440, y: 400 + index * 170,
          mojo: { version: '1.0', device: [device], event: point.path, eventKind: 'Parameter',
            paramType: 'Boolean', boolParamFilter: 'Any', onebased: point.onebased }, wires: [[tagId]] })
        nodes.push({ id: tagId, type: 'change', z: subflowId,
          name: `Identify availability ${device} ${point.path}`, x: 900, y: 370 + index * 170,
          rules: [
            { t: 'set', p: 'kind', pt: 'msg', to: 'device-availability', tot: 'str' },
            { t: 'set', p: 'device', pt: 'msg', to: device, tot: 'str' },
            { t: 'set', p: 'path', pt: 'msg', to: point.path, tot: 'str' }
          ], wires: [[]] })
      }
    }
    return target
  }

  for (const [id, { control, binding }] of routes) {
    if (!binding?.device) throw new Error(`Missing device binding: ${id}`)
    if (control.mode !== 'read') {
      if (!binding.writePath) throw new Error(`Missing write path: ${id}`)
      const target = metadata(binding.device, binding.writePath, control.type, 'w', control.adapter)
      const key = JSON.stringify([target.device, target.path])
      if (!writeTargets.has(key)) {
        const nodeId = `${scopeId}-write-${writeTargets.size + 1}`
        writeTargets.set(key, nodeId)
        nodes.push({
          id: nodeId, type: 'Command', z: subflowId,
          name: `Write ${target.device} ${target.path}`,
          x: 1860, y: 10 + writeTargets.size * 110,
          mojo: { version: '1.0', device: [target.device], command: target.path,
            onebased: target.onebased, cmdvalue: 'Message payload' },
          wires: [[]]
        })
      }
      commandRules.push({ t: 'eq', v: id, vt: 'str' })
      commandWires.push([writeTargets.get(key)])
    }

    if (control.mode !== 'write') {
      if (!binding.readPath) throw new Error(`Missing read path: ${id}`)
      const target = metadata(binding.device, binding.readPath, control.type, 'r', control.adapter)
      if (target.meter) {
        const meter = meterRoute(target.meter)
        if (control.mode !== 'read' || control.adapter !== 'meter') throw Error(`Meter is read-only: ${id}`)
        const key = JSON.stringify([target.device, meter.streamId])
        const previous = meterStreams.get(key)
        if (previous) {
          if (JSON.stringify(previous.meter) !== JSON.stringify(meter) || previous.onebased !== target.onebased) {
            throw Error(`Conflicting meter stream: ${meter.streamId}`)
          }
          continue
        }
        const index = meterStreams.size + 1
        const statusId = `${scopeId}-meter-read-${index}`
        const tagIds = []
        meterStreams.set(key, { meter, onebased: target.onebased, statusId, tagIds })
        for (const [role, path] of [['manifest', meter.manifestPath], ['frame', meter.eventPath]]) {
          const eventId = `${scopeId}-meter-${role}-${index}`
          const tagId = `${eventId}-tag`
          tagIds.push(tagId)
          const y = 540 + (index - 1) * 280 + (role === 'frame' ? 140 : 0)
          if (role === 'manifest') nodes.push({
            id: statusId, type: 'Status', z: subflowId, name: `Read meter manifest ${target.device}`,
            x: 440, y: y - 60, mojo: { version: '1.0', device: [target.device],
              parameter: path, onebased: target.onebased }, wires: [[tagId]]
          })
          nodes.push({ id: eventId, type: 'Event', z: subflowId,
            name: `Watch meter ${role} ${target.device} ${meter.streamId}`, x: 440, y,
            mojo: { version: '1.0', device: [target.device], event: path,
              eventKind: role === 'frame' ? 'Event' : 'Parameter', paramType: 'String',
              onebased: target.onebased }, wires: [[tagId]] })
          nodes.push({ id: tagId, type: 'change', z: subflowId,
            name: `Identify meter ${role} ${target.device}`, x: 1000, y,
            rules: [
              { t: 'set', p: 'kind', pt: 'msg', to: 'device-meter-' + role, tot: 'str' },
              { t: 'set', p: 'device', pt: 'msg', to: target.device, tot: 'str' },
              { t: 'set', p: 'path', pt: 'msg', to: path, tot: 'str' },
              { t: 'set', p: 'streamId', pt: 'msg', to: meter.streamId, tot: 'str' }
            ], wires: [[]] })
        }
        continue
      }
      if (target.xySeries) {
        const series = xySeriesRoute(target.xySeries)
        if (control.mode !== 'read' || control.adapter !== 'xy-series') {
          throw Error(`XY-series is read-only: ${id}`)
        }
        const key = JSON.stringify([target.device, series.streamId])
        const previous = xySeriesStreams.get(key)
        if (previous) {
          if (JSON.stringify(previous.series) !== JSON.stringify(series) || previous.onebased !== target.onebased) {
            throw Error(`Conflicting xy-series stream: ${series.streamId}`)
          }
          continue
        }
        const index = xySeriesStreams.size + 1
        const statusId = `${scopeId}-xy-series-read-${index}`
        const tagIds = []
        xySeriesStreams.set(key, { series, onebased: target.onebased, statusId, tagIds })
        for (const [role, path] of [['manifest', series.manifestPath], ['frame', series.eventPath]]) {
          const eventId = `${scopeId}-xy-series-${role}-${index}`
          const tagId = `${eventId}-tag`
          tagIds.push(tagId)
          const y = 540 + (index - 1) * 280 + (role === 'frame' ? 140 : 0)
          if (role === 'manifest') nodes.push({
            id: statusId, type: 'Status', z: subflowId, name: `Read xy-series manifest ${target.device}`,
            x: 440, y: y - 60, mojo: { version: '1.0', device: [target.device],
              parameter: path, onebased: target.onebased }, wires: [[tagId]]
          })
          nodes.push({ id: eventId, type: 'Event', z: subflowId,
            name: `Watch xy-series ${role} ${target.device} ${series.streamId}`, x: 440, y,
            mojo: { version: '1.0', device: [target.device], event: path,
              eventKind: role === 'frame' ? 'Event' : 'Parameter', paramType: 'String',
              onebased: target.onebased }, wires: [[tagId]] })
          nodes.push({ id: tagId, type: 'change', z: subflowId,
            name: `Identify xy-series ${role} ${target.device}`, x: 1000, y,
            rules: [
              { t: 'set', p: 'kind', pt: 'msg', to: 'device-xy-series-' + role, tot: 'str' },
              { t: 'set', p: 'device', pt: 'msg', to: target.device, tot: 'str' },
              { t: 'set', p: 'path', pt: 'msg', to: path, tot: 'str' },
              { t: 'set', p: 'streamId', pt: 'msg', to: series.streamId, tot: 'str' }
            ], wires: [[]] })
        }
        continue
      }
      const key = JSON.stringify([target.device, target.path])
      if (readTargets.has(key)) continue
      const index = readTargets.size + 1
      const statusId = `${scopeId}-read-${index}`
      const eventId = `${scopeId}-watch-${index}`
      const tagId = `${scopeId}-tag-${index}`
      readTargets.set(key, { statusId, eventId, tagId })
      const event = supportedTypes[target.type]
      nodes.push({
        id: statusId, type: 'Status', z: subflowId,
        name: `Read ${target.device} ${target.path}`,
        x: 440, y: 360 + index * 170,
        mojo: { version: '1.0', device: [target.device], parameter: target.path,
          onebased: target.onebased },
        wires: [[tagId]]
      })
      nodes.push({
        id: eventId, type: 'Event', z: subflowId,
        name: `Watch ${target.device} ${target.path}`,
        x: 440, y: 420 + index * 170,
        mojo: { version: '1.0', device: [target.device], event: target.path,
          eventKind: 'Parameter', paramType: event.eventType,
          onebased: target.onebased, ...event.eventOptions },
        wires: [[tagId]]
      })
      nodes.push({
        id: tagId, type: 'change', z: subflowId,
        name: `Identify ${target.device} ${target.path}`,
        x: 900, y: 390 + index * 170,
        rules: [
          { t: 'set', p: 'kind', pt: 'msg', to: 'device-feedback', tot: 'str' },
          { t: 'set', p: 'device', pt: 'msg', to: target.device, tot: 'str' },
          { t: 'set', p: 'path', pt: 'msg', to: target.path, tot: 'str' }
        ],
        wires: [[]]
      })
    }
  }

  const commandSwitchId = `${scopeId}-commands`
  // Ordinary feedback, Meter, and XY-series each get a separate vertical band.
  for (const node of nodes) {
    if (node.id.startsWith(`${scopeId}-health-`)) {
      node.y += readTargets.size * 170 + (meterStreams.size + xySeriesStreams.size) * 280
    }
    if (node.id.startsWith(`${scopeId}-meter-`) || node.id.startsWith(`${scopeId}-xy-series-`)) {
      node.y += readTargets.size * 170
      if (node.id.startsWith(`${scopeId}-xy-series-`)) node.y += meterStreams.size * 280
    }
  }
  const routerId = `${scopeId}-router`
  if (commandRules.length) {
    nodes.push({
      id: commandSwitchId, type: 'switch', z: subflowId,
      name: 'Control ID', property: 'controlId', propertyType: 'msg',
      x: 1440, y: 140,
      rules: commandRules, checkall: 'false', repair: false,
      outputs: commandRules.length, wires: commandWires
    })
  }
  nodes.push({
    id: routerId, type: 'switch', z: subflowId,
    name: 'Command or initial read', property: 'kind', propertyType: 'msg',
    x: 430, y: 150,
    rules: [
      { t: 'eq', v: 'bound-command', vt: 'str' },
      { t: 'eq', v: 'read-all', vt: 'str' }
    ],
    checkall: 'false', repair: false, outputs: 2,
    wires: [commandRules.length ? [commandSwitchId] : [],
      [...readTargets.values(), ...meterStreams.values(), ...xySeriesStreams.values(), ...healthTargets.values()].map(target => target.statusId)]
  })
  const subflow = {
    id: subflowId, type: 'subflow', name: `Binding bridge ${scopeId}`,
    info: 'Generated panel binding bridge. Requires a Controller node and authenticated command source.',
    category: 'panel binding',
    in: [{ x: 170, y: 150, wires: [{ id: routerId }] }],
    out: readTargets.size || meterStreams.size || xySeriesStreams.size || healthTargets.size
      ? [{ x: meterStreams.size || xySeriesStreams.size ? 1600 : 1290,
        y: Math.round((390 + (readTargets.size + meterStreams.size + xySeriesStreams.size + 1) * 85) / 10) * 10,
        wires: [...readTargets.values()].map(target => ({ id: target.tagId, port: 0 }))
          .concat([...meterStreams.values()].flatMap(target => target.tagIds.map(id => ({ id, port: 0 }))))
          .concat([...xySeriesStreams.values()].flatMap(target => target.tagIds.map(id => ({ id, port: 0 }))))
          .concat([...healthTargets.values()].map(target => ({ id: target.tagId, port: 0 }))) }]
      : [],
    env: [], meta: {}, color: '#96bca7'
  }
  return {
    nodes: [subflow, ...nodes],
    manifest: {
      subflowId,
      controls: routes.size,
      nativeReads: readTargets.size + meterStreams.size + xySeriesStreams.size + healthTargets.size,
      ...(healthTargets.size ? { nativeAvailabilityReads: healthTargets.size } : {}),
      nativeMeterStreams: meterStreams.size,
      nativeXYSeriesStreams: xySeriesStreams.size,
      nativeWrites: writeTargets.size,
      requiresController: true,
      initialReadMessage: { kind: 'read-all' }
    }
  }
}

module.exports = { compileNativeBindingPlan }
